import numpy as np
a=np.load('source_pixels.npz')['rgb']
# ball positions using color at each frame. take cyan mask b>r+20, b>g+8 and b>90 within x110:140 y70:115, calculate circle center using median x and top/bottom.
for i in range(96):
 p=a[i].astype(int);r,g,b=p[:,:,0],p[:,:,1],p[:,:,2]
 yy,xx=np.where((b>90)&(b>r+25)&(b>g+15)&(np.indices(b.shape)[0]>=70)&(np.indices(b.shape)[0]<=115)&(np.indices(b.shape)[1]>=110)&(np.indices(b.shape)[1]<=145))
 if len(xx): print(i,len(xx),xx.min(),xx.max(),yy.min(),yy.max(),round(xx.mean(),2),round(yy.mean(),2))
 else: print(i,0)
